GUIDE = ("سيرورة المقطع: 1) التقويم التشخيصي لقياس المكتسبات القبلية؛ 2) وضعية الانطلاق (تستمد من الكفاءة الختامية)؛ "
         "وضعيات جزئية لتعلم الموارد (الأداءات والنشاطات) في شكل وضعيات تعلمية، يعقب كل منها وضعية تعلم الإدماج الجزئي؛ "
         "3) وضعية إدماج الموارد (الإدماج الكلي، تنجز خلال الأسبوع ما قبل الاختبار)؛ 4) وضعية تقويم الكفاءة (هي نفسها الاختبار)؛ "
         "5) المعالجة البيداغوجية المحتملة (هي تصحيح الاختبار). معايير تقويم الكفاءات: الوجاهة، الاستعمال السليم لأدوات المادة، الانسجام، الإتقان؛ "
         "ومعايير تملك الموارد: اكتساب معارف، توظيف معارف، اكتساب قيم و/أو اتخاذ مواقف.")


def seq(prefix, i, item, src, dom):
    term, title, comp, res, sits = item
    lessons = [{"title": "التقويم التشخيصي + وضعية الانطلاق", "domain": dom,
                "hint": "قياس المكتسبات القبلية ثم عرض وضعية الانطلاق المستمدة من الكفاءة الختامية."}]
    lessons += [{"title": f"الوضعية التعلمية {k:02d}: {s}", "domain": dom, "hint": f"وضعية تعلم الإدماج الجزئي: {a}"}
                for k, (s, a) in enumerate(sits, 1)]
    lessons += [{"title": "وضعية إدماج الموارد (الإدماج الكلي)", "domain": dom,
                 "hint": "وضعية إدماجية حول موارد المقطع كلها، تنجز خلال الأسبوع ما قبل الاختبار."},
                {"title": "المعالجة البيداغوجية", "domain": dom}]
    return {"title": f"{prefix}المقطع {i:02d}: {title}", "term": TERM[term], "domain": dom, "official": {
        "source": src,
        "levels": {"الكفاءة الختامية": comp},
        "resources": {"هيكلة الموارد المعرفية المستهدفة": "؛ ".join(res),
                      "الوضعيات التعلمية": " | ".join(f"{k}) {s}" for k, (s, _) in enumerate(sits, 1))},
        "situation": "وضعية الانطلاق تستمد من الكفاءة الختامية للمقطع.",
        "tasks": ["وضعيات جزئية لتعلم الموارد يعقب كل منها وضعية تعلم الإدماج الجزئي", "وضعية إدماج الموارد (الإدماج الكلي)", "وضعية تقويم الكفاءة", "المعالجة البيداغوجية"],
        "criteria": ["اكتساب معارف", "توظيف معارف", "اكتساب قيم و/أو اتخاذ مواقف", "الوجاهة، الاستعمال السليم لأدوات المادة، الانسجام، الإتقان"]},
        "lessons": lessons}


if __name__ == "__main__":
    path = Path(__file__).parent / "curriculum.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    hg = next(x for x in data["subjects"] if x["id"] == "hisgeo")
    cv = next(x for x in data["subjects"] if x["id"] == "civic")
    hg["domains"] = ["التاريخ", "الجغرافيا"]
    cv["domains"] = ["الحياة الجماعية", "الحياة المدنية", "الحياة الديمقراطية ومؤسسات الجمهورية"]
    for n in (1, 2, 3, 4):
        hsrc, gsrc = SRC.format(s="التاريخ", n=n), SRC.format(s="الجغرافيا", n=n)
        hg["levels"][str(n)] = [seq("تاريخ – ", i, it, hsrc, "التاريخ") for i, it in enumerate(HIST[n], 1)] + \
                               [seq("جغرافيا – ", i, it, gsrc, "الجغرافيا") for i, it in enumerate(GEO[n], 1)]
        csrc = SRC.format(s="التربية المدنية", n=n)
        cv["levels"][str(n)] = [seq("", i, it, csrc, it[1]) for i, it in enumerate(CIV[n], 1)]
        for s in (hg, cv):
            s.setdefault("guidelines", {})[str(n)] = GUIDE
        hg.setdefault("verified", {})[str(n)] = f"{hsrc} + {gsrc}"
        cv.setdefault("verified", {})[str(n)] = csrc
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    print("ok")
